-- PostgreSQL 17: cấu trúc mới tương ứng mapping EF6. Chỉ chạy trên database trống.

BEGIN;

CREATE SEQUENCE public.row_version_sequence;

CREATE FUNCTION public.set_row_version() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN NEW."RowVersion" := int8send(nextval('public.row_version_sequence')); RETURN NEW; END $$;

CREATE TABLE public."app_Function" (
    "FunctionId" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "ParentFunctionId" int4,
    "FunctionCode" varchar(100) NOT NULL,
    "DisplayName" varchar(200) NOT NULL,
    "Description" varchar(500),
    "NavigationTarget" varchar(300),
    "SortOrder" int4 DEFAULT 0 NOT NULL,
    "IsVisible" bool DEFAULT true NOT NULL,
    "IsActive" bool DEFAULT true NOT NULL,
    "DevelopmentStatus" varchar(20) DEFAULT 'NOT_STARTED' NOT NULL,
    "IsWide" bool DEFAULT true NOT NULL,
    "UpdatedAt" timestamp,
    "RowVersion" bytea DEFAULT int8send(nextval('public.row_version_sequence')) NOT NULL,
    PRIMARY KEY ("FunctionId")
);

CREATE TRIGGER row_version BEFORE INSERT OR UPDATE ON public."app_Function" FOR EACH ROW EXECUTE FUNCTION public.set_row_version();

CREATE TABLE public."audit_AuditLog" (
    "AuditLogId" int8 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "CreatedAt" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    "UserId" varchar(10),
    "AttemptedUserId" varchar(100),
    "ActionCode" varchar(100) NOT NULL,
    "EntityName" varchar(128),
    "EntityId" varchar(100),
    "Description" varchar(1000),
    "MachineName" varchar(100),
    "IpAddress" varchar(50),
    "CorrelationId" uuid DEFAULT gen_random_uuid() NOT NULL,
    "DataJson" text,
    PRIMARY KEY ("AuditLogId")
);

CREATE TABLE public."dm_Department" (
    "DepartmentId" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "DepartmentCode" varchar(30) NOT NULL,
    "DepartmentName" varchar(200) NOT NULL,
    "ParentDepartmentId" int4,
    "SortOrder" int4 DEFAULT 0 NOT NULL,
    "IsActive" bool DEFAULT true NOT NULL,
    "UpdatedAt" timestamp,
    "RowVersion" bytea DEFAULT int8send(nextval('public.row_version_sequence')) NOT NULL,
    PRIMARY KEY ("DepartmentId")
);

CREATE TRIGGER row_version BEFORE INSERT OR UPDATE ON public."dm_Department" FOR EACH ROW EXECUTE FUNCTION public.set_row_version();

CREATE TABLE public."hr_EmployeeProfile" (
    "EmployeeProfileId" int8 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "EmployeeCode" varchar(10) NOT NULL,
    "DisplayNameTW" varchar(100),
    "DisplayNameVN" varchar(200) NOT NULL,
    "DepartmentId" int4 DEFAULT 0 NOT NULL,
    "JobTitleId" int4,
    "WorkEmail" varchar(200),
    "WorkPhone" varchar(30),
    "HireDate" timestamp,
    "ResignDate" timestamp,
    "EmploymentStatus" int2 DEFAULT 0 NOT NULL,
    "UpdatedAt" timestamp,
    "RowVersion" bytea DEFAULT int8send(nextval('public.row_version_sequence')) NOT NULL,
    PRIMARY KEY ("EmployeeProfileId")
);

CREATE TRIGGER row_version BEFORE INSERT OR UPDATE ON public."hr_EmployeeProfile" FOR EACH ROW EXECUTE FUNCTION public.set_row_version();

CREATE TABLE public."auth_GroupRole" (
    "GroupId" int4 DEFAULT 0 NOT NULL,
    "RoleId" int4 DEFAULT 0 NOT NULL,
    "AssignedAt" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    "AssignedByUserId" varchar(10),
    "IsActive" bool DEFAULT true NOT NULL,
    PRIMARY KEY ("GroupId", "RoleId")
);

CREATE TABLE public."dm_JobTitle" (
    "JobTitleId" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "JobTitleCode" varchar(30) NOT NULL,
    "JobTitleName" varchar(200) NOT NULL,
    "SortOrder" int4 DEFAULT 0 NOT NULL,
    "IsActive" bool DEFAULT true NOT NULL,
    "UpdatedAt" timestamp,
    "RowVersion" bytea DEFAULT int8send(nextval('public.row_version_sequence')) NOT NULL,
    PRIMARY KEY ("JobTitleId")
);

CREATE TRIGGER row_version BEFORE INSERT OR UPDATE ON public."dm_JobTitle" FOR EACH ROW EXECUTE FUNCTION public.set_row_version();

CREATE TABLE public."auth_Permission" (
    "PermissionId" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "FunctionId" int4 DEFAULT 0 NOT NULL,
    "ActionCode" varchar(30) NOT NULL,
    "PermissionCode" varchar(150) NOT NULL,
    "DisplayName" varchar(200) NOT NULL,
    "IsActive" bool DEFAULT true NOT NULL,
    PRIMARY KEY ("PermissionId")
);

CREATE TABLE public."auth_RolePermission" (
    "RoleId" int4 DEFAULT 0 NOT NULL,
    "PermissionId" int4 DEFAULT 0 NOT NULL,
    "AssignedAt" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    "AssignedByUserId" varchar(10),
    "IsActive" bool DEFAULT true NOT NULL,
    PRIMARY KEY ("RoleId", "PermissionId")
);

CREATE TABLE public."auth_Role" (
    "RoleId" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "RoleCode" varchar(80) NOT NULL,
    "RoleName" varchar(200) NOT NULL,
    "Description" varchar(500),
    "IsSystemRole" bool DEFAULT false NOT NULL,
    "IsActive" bool DEFAULT true NOT NULL,
    "UpdatedAt" timestamp,
    "RowVersion" bytea DEFAULT int8send(nextval('public.row_version_sequence')) NOT NULL,
    PRIMARY KEY ("RoleId")
);

CREATE TRIGGER row_version BEFORE INSERT OR UPDATE ON public."auth_Role" FOR EACH ROW EXECUTE FUNCTION public.set_row_version();

CREATE TABLE public."auth_SecurityGroup" (
    "GroupId" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "GroupCode" varchar(80) NOT NULL,
    "GroupName" varchar(200) NOT NULL,
    "Description" varchar(500),
    "IsSystemGroup" bool DEFAULT false NOT NULL,
    "IsActive" bool DEFAULT true NOT NULL,
    "UpdatedAt" timestamp,
    "RowVersion" bytea DEFAULT int8send(nextval('public.row_version_sequence')) NOT NULL,
    PRIMARY KEY ("GroupId")
);

CREATE TRIGGER row_version BEFORE INSERT OR UPDATE ON public."auth_SecurityGroup" FOR EACH ROW EXECUTE FUNCTION public.set_row_version();

CREATE TABLE public."sys_SystemSetting" (
    "SettingKey" varchar(100) NOT NULL,
    "SettingValue" varchar(1000) NOT NULL,
    "DisplayName" varchar(200) NOT NULL,
    "Description" varchar(500),
    "ValueType" varchar(20) NOT NULL,
    "MinimumValue" int4,
    "MaximumValue" int4,
    "IsSensitive" bool DEFAULT false NOT NULL,
    "UpdatedByUserId" varchar(10),
    "UpdatedAt" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    "RowVersion" bytea DEFAULT int8send(nextval('public.row_version_sequence')) NOT NULL,
    PRIMARY KEY ("SettingKey")
);

CREATE TRIGGER row_version BEFORE INSERT OR UPDATE ON public."sys_SystemSetting" FOR EACH ROW EXECUTE FUNCTION public.set_row_version();

CREATE TABLE public."auth_UserAccount" (
    "UserId" varchar(10) NOT NULL,
    "EmployeeProfileId" int8,
    "CachedDomainPasswordHash" varchar(500),
    "LastDomainValidatedAt" timestamp,
    "SecurityStamp" uuid DEFAULT gen_random_uuid() NOT NULL,
    "FailedLoginCount" int4 DEFAULT 0 NOT NULL,
    "LockoutEndUtc" timestamp,
    "LastLoginAt" timestamp,
    "IsActive" bool DEFAULT true NOT NULL,
    "CreatedAt" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    "UpdatedAt" timestamp,
    "RowVersion" bytea DEFAULT int8send(nextval('public.row_version_sequence')) NOT NULL,
    PRIMARY KEY ("UserId")
);

CREATE TRIGGER row_version BEFORE INSERT OR UPDATE ON public."auth_UserAccount" FOR EACH ROW EXECUTE FUNCTION public.set_row_version();

CREATE TABLE public."auth_UserGroup" (
    "UserId" varchar(10) NOT NULL,
    "GroupId" int4 DEFAULT 0 NOT NULL,
    "ExpiresAt" timestamp,
    "IsActive" bool DEFAULT true NOT NULL,
    PRIMARY KEY ("UserId", "GroupId")
);

CREATE TABLE public."sparepart_InspectionAttachment" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Thread" text,
    "EncryptionName" text,
    "ActualName" text,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_InspectionBatch" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "BatchName" text,
    "CreatedDate" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    "ExpiryDate" timestamp,
    "NotifyNo" int4,
    "ReportDate" timestamp,
    "IsCancelled" bool DEFAULT false NOT NULL,
    "CancelledBy" text,
    "CancelledDate" timestamp,
    "CancelReason" text,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_InspectionItem" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "BatchId" int4 DEFAULT 0 NOT NULL,
    "MaterialId" int4 DEFAULT 0 NOT NULL,
    "InitialQuantity" float8 DEFAULT 0 NOT NULL,
    "ActualQuantity" float8,
    "ConfirmationDate" timestamp,
    "ConfirmedBy" text,
    "IsComplete" bool,
    "Description" text,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_MachineMaterial" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "MachineId" int4 DEFAULT 0 NOT NULL,
    "MaterialId" int4 DEFAULT 0 NOT NULL,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_Machine" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "IdDept" text,
    "DisplayName" text,
    "Location" text,
    "Quantity" int4 DEFAULT 0 NOT NULL,
    "ImpLevel" text,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_MaterialPhoto" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "MaterialId" int4 DEFAULT 0 NOT NULL,
    "EncryptionName" text,
    "ActualName" text,
    "UploadedBy" text,
    "UploadedDate" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    "IsActive" bool DEFAULT true NOT NULL,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_Material" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "IdDept" text,
    "Code" text,
    "DisplayName" text,
    "TypeUse" text,
    "Location" text,
    "IdUnit" int4 DEFAULT 0 NOT NULL,
    "MinQuantity" float8 DEFAULT 0 NOT NULL,
    "QuantityInStorage" float8 DEFAULT 0 NOT NULL,
    "QuantityInMachine" float8 DEFAULT 0 NOT NULL,
    "ExpDate" timestamp,
    "IdManager" text,
    "DelTime" timestamp,
    "UserDel" text,
    "Price" int4 DEFAULT 0 NOT NULL,
    "IsDisable" bool,
    "DisabledBy" text,
    "DisabledDate" timestamp,
    "EnabledBy" text,
    "EnabledDate" timestamp,
    "ReplacementMaterialId" int4,
    "ReplacementDate" timestamp,
    "BaseMaterialId" int4,
    "IsRecoveredOld" bool DEFAULT false NOT NULL,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_Price" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "MaterialId" int4 DEFAULT 0 NOT NULL,
    "Price" int4 DEFAULT 0 NOT NULL,
    "ChangedBy" text,
    "ChangedAt" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_RecoveryEvidence" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "RecoveryTicketId" int4 DEFAULT 0 NOT NULL,
    "ActualName" text,
    "EncryptionName" text,
    "FileExt" text,
    "UploadedBy" text,
    "UploadedDate" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    "IsActive" bool DEFAULT true NOT NULL,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_RecoveryGuide" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "Title" text,
    "ActualName" text,
    "EncryptionName" text,
    "FileExt" text,
    "DisplayOrder" int4 DEFAULT 0 NOT NULL,
    "IsActive" bool DEFAULT true NOT NULL,
    "UploadedBy" text,
    "UploadedDate" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_RecoveryTicket" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "TicketNo" text,
    "IssueTransactionId" int4 DEFAULT 0 NOT NULL,
    "RestockInTransactionId" int4,
    "NewMaterialId" int4 DEFAULT 0 NOT NULL,
    "OldBaseMaterialId" int4 DEFAULT 0 NOT NULL,
    "OldRecoveryMaterialId" int4,
    "RecoveryOption" text,
    "Quantity" float8 DEFAULT 0 NOT NULL,
    "SourceStorageId" int4 DEFAULT 0 NOT NULL,
    "RestockStorageId" int4,
    "AssignedUserId" varchar(10),
    "PlannedDisposeDate" timestamp,
    "ActualDisposeDate" timestamp,
    "Status" text,
    "Description" text,
    "ResultNote" text,
    "EvidenceSubmittedDate" timestamp,
    "CompletedBy" text,
    "CompletedDate" timestamp,
    "CancelledBy" text,
    "CancelledDate" timestamp,
    "CancelReason" text,
    "CreatedBy" text,
    "CreatedDate" timestamp DEFAULT (CURRENT_TIMESTAMP AT TIME ZONE 'UTC') NOT NULL,
    "UpdatedBy" text,
    "UpdatedDate" timestamp,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_Storage" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "DisplayName" text,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_Transaction" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "StorageId" int4 DEFAULT 0 NOT NULL,
    "MaterialId" int4 DEFAULT 0 NOT NULL,
    "Quantity" float8 DEFAULT 0 NOT NULL,
    "TransactionType" text,
    "CreatedDate" timestamp,
    "AftQuantity" float8,
    "TotalQuantity" float8,
    "UserDo" text,
    "Desc" text,
    "NotifyDate" timestamp,
    PRIMARY KEY ("Id")
);

CREATE TABLE public."sparepart_Unit" (
    "Id" int4 GENERATED BY DEFAULT AS IDENTITY NOT NULL,
    "DisplayName" text,
    PRIMARY KEY ("Id")
);

CREATE VIEW public."vw_sparepart_User" AS SELECT u."UserId" AS "Id",
COALESCE(NULLIF(e."DisplayNameTW", ''), NULLIF(e."DisplayNameVN", ''), u."UserId") AS "DisplayName",
NULL::text AS "SecondaryPassword",
u."CreatedAt" AS "DateCreate",
COALESCE(d."DepartmentCode", '') AS "IdDepartment",
e."DisplayNameVN" AS "DisplayNameVN",
NULL::timestamp AS "DOB",
NULL::text AS "CitizenID",
NULL::text AS "Nationality",
NULL::text AS "JobCode",
NULL::text AS "PCName",
NULL::text AS "IPAddress",
NULL::text AS "Addr",
NULL::text AS "PhoneNum1",
NULL::text AS "PhoneNum2",
CASE WHEN u."IsActive" THEN 0 ELSE 1 END AS "Status",
NULL::bool AS "Sex",
NULL::text AS "ActualJobCode",
u."UpdatedAt" AS "LastUpdate",
NULL::timestamp AS "ResignPlan",
NULL::text AS "RecognizedEducation",
NULL::text AS "EducationName",
NULL::timestamp AS "ResignDate",
NULL::timestamp AS "JobEffectiveDate" FROM public."auth_UserAccount" u LEFT JOIN public."hr_EmployeeProfile" e ON e."EmployeeProfileId"=u."EmployeeProfileId" LEFT JOIN public."dm_Department" d ON d."DepartmentId"=e."DepartmentId";

CREATE VIEW public."vw_sparepart_Department" AS SELECT d."DepartmentCode" AS "Id",
d."DepartmentId" AS "IdChild",
d."ParentDepartmentId" AS "IdParent",
d."DepartmentName" AS "DisplayName",
d."DepartmentName" AS "DisplayNameVN",
false AS "IsGroup",
NULL::int4 AS "AuthorizedHeadcount",
d."IsActive" AS "IsActive" FROM public."dm_Department" d;

ALTER TABLE public."dm_Department" ADD UNIQUE ("DepartmentCode");

ALTER TABLE public."dm_JobTitle" ADD UNIQUE ("JobTitleCode");

ALTER TABLE public."hr_EmployeeProfile" ADD UNIQUE ("EmployeeCode");

ALTER TABLE public."auth_UserAccount" ADD UNIQUE ("EmployeeProfileId");

ALTER TABLE public."auth_Role" ADD UNIQUE ("RoleCode");

ALTER TABLE public."auth_SecurityGroup" ADD UNIQUE ("GroupCode");

ALTER TABLE public."auth_Permission" ADD UNIQUE ("PermissionCode");

ALTER TABLE public."app_Function" ADD UNIQUE ("FunctionCode");

ALTER TABLE public."dm_Department" ADD FOREIGN KEY ("ParentDepartmentId") REFERENCES public."dm_Department" ("DepartmentId");

CREATE INDEX ON public."dm_Department" ("ParentDepartmentId");

ALTER TABLE public."hr_EmployeeProfile" ADD FOREIGN KEY ("DepartmentId") REFERENCES public."dm_Department" ("DepartmentId");

CREATE INDEX ON public."hr_EmployeeProfile" ("DepartmentId");

ALTER TABLE public."hr_EmployeeProfile" ADD FOREIGN KEY ("JobTitleId") REFERENCES public."dm_JobTitle" ("JobTitleId");

CREATE INDEX ON public."hr_EmployeeProfile" ("JobTitleId");

ALTER TABLE public."auth_UserAccount" ADD FOREIGN KEY ("EmployeeProfileId") REFERENCES public."hr_EmployeeProfile" ("EmployeeProfileId");

CREATE INDEX ON public."auth_UserAccount" ("EmployeeProfileId");

ALTER TABLE public."auth_UserGroup" ADD FOREIGN KEY ("UserId") REFERENCES public."auth_UserAccount" ("UserId");

CREATE INDEX ON public."auth_UserGroup" ("UserId");

ALTER TABLE public."auth_UserGroup" ADD FOREIGN KEY ("GroupId") REFERENCES public."auth_SecurityGroup" ("GroupId");

CREATE INDEX ON public."auth_UserGroup" ("GroupId");

ALTER TABLE public."auth_GroupRole" ADD FOREIGN KEY ("GroupId") REFERENCES public."auth_SecurityGroup" ("GroupId");

CREATE INDEX ON public."auth_GroupRole" ("GroupId");

ALTER TABLE public."auth_GroupRole" ADD FOREIGN KEY ("RoleId") REFERENCES public."auth_Role" ("RoleId");

CREATE INDEX ON public."auth_GroupRole" ("RoleId");

ALTER TABLE public."auth_RolePermission" ADD FOREIGN KEY ("RoleId") REFERENCES public."auth_Role" ("RoleId");

CREATE INDEX ON public."auth_RolePermission" ("RoleId");

ALTER TABLE public."auth_RolePermission" ADD FOREIGN KEY ("PermissionId") REFERENCES public."auth_Permission" ("PermissionId");

CREATE INDEX ON public."auth_RolePermission" ("PermissionId");

ALTER TABLE public."auth_Permission" ADD FOREIGN KEY ("FunctionId") REFERENCES public."app_Function" ("FunctionId");

CREATE INDEX ON public."auth_Permission" ("FunctionId");

ALTER TABLE public."app_Function" ADD FOREIGN KEY ("ParentFunctionId") REFERENCES public."app_Function" ("FunctionId");

CREATE INDEX ON public."app_Function" ("ParentFunctionId");

ALTER TABLE public."sys_SystemSetting" ADD FOREIGN KEY ("UpdatedByUserId") REFERENCES public."auth_UserAccount" ("UserId");

CREATE INDEX ON public."sys_SystemSetting" ("UpdatedByUserId");

ALTER TABLE public."sparepart_Material" ADD FOREIGN KEY ("IdUnit") REFERENCES public."sparepart_Unit" ("Id");

CREATE INDEX ON public."sparepart_Material" ("IdUnit");

ALTER TABLE public."sparepart_Material" ADD FOREIGN KEY ("ReplacementMaterialId") REFERENCES public."sparepart_Material" ("Id");

CREATE INDEX ON public."sparepart_Material" ("ReplacementMaterialId");

ALTER TABLE public."sparepart_Material" ADD FOREIGN KEY ("BaseMaterialId") REFERENCES public."sparepart_Material" ("Id");

CREATE INDEX ON public."sparepart_Material" ("BaseMaterialId");

ALTER TABLE public."sparepart_MachineMaterial" ADD FOREIGN KEY ("MachineId") REFERENCES public."sparepart_Machine" ("Id");

CREATE INDEX ON public."sparepart_MachineMaterial" ("MachineId");

ALTER TABLE public."sparepart_MachineMaterial" ADD FOREIGN KEY ("MaterialId") REFERENCES public."sparepart_Material" ("Id");

CREATE INDEX ON public."sparepart_MachineMaterial" ("MaterialId");

ALTER TABLE public."sparepart_Transaction" ADD FOREIGN KEY ("StorageId") REFERENCES public."sparepart_Storage" ("Id");

CREATE INDEX ON public."sparepart_Transaction" ("StorageId");

ALTER TABLE public."sparepart_Transaction" ADD FOREIGN KEY ("MaterialId") REFERENCES public."sparepart_Material" ("Id");

CREATE INDEX ON public."sparepart_Transaction" ("MaterialId");

ALTER TABLE public."sparepart_Price" ADD FOREIGN KEY ("MaterialId") REFERENCES public."sparepart_Material" ("Id");

CREATE INDEX ON public."sparepart_Price" ("MaterialId");

ALTER TABLE public."sparepart_MaterialPhoto" ADD FOREIGN KEY ("MaterialId") REFERENCES public."sparepart_Material" ("Id");

CREATE INDEX ON public."sparepart_MaterialPhoto" ("MaterialId");

ALTER TABLE public."sparepart_InspectionItem" ADD FOREIGN KEY ("BatchId") REFERENCES public."sparepart_InspectionBatch" ("Id");

CREATE INDEX ON public."sparepart_InspectionItem" ("BatchId");

ALTER TABLE public."sparepart_InspectionItem" ADD FOREIGN KEY ("MaterialId") REFERENCES public."sparepart_Material" ("Id");

CREATE INDEX ON public."sparepart_InspectionItem" ("MaterialId");

ALTER TABLE public."sparepart_RecoveryTicket" ADD FOREIGN KEY ("IssueTransactionId") REFERENCES public."sparepart_Transaction" ("Id");

CREATE INDEX ON public."sparepart_RecoveryTicket" ("IssueTransactionId");

ALTER TABLE public."sparepart_RecoveryTicket" ADD FOREIGN KEY ("RestockInTransactionId") REFERENCES public."sparepart_Transaction" ("Id");

CREATE INDEX ON public."sparepart_RecoveryTicket" ("RestockInTransactionId");

ALTER TABLE public."sparepart_RecoveryTicket" ADD FOREIGN KEY ("NewMaterialId") REFERENCES public."sparepart_Material" ("Id");

