ALTER TABLE public."auth_UserAccount" ADD CHECK ("UserId" ~ '^VNW[0-9]{7}$');

ALTER TABLE public."app_Function" ADD CHECK ("DevelopmentStatus" IN ('NOT_STARTED','IN_PROGRESS','COMPLETED'));

ALTER TABLE public."sys_SystemSetting" ADD CHECK ("ValueType" IN ('STRING','INTEGER','BOOLEAN','PATH'));

COMMIT;
